function validate([arr1, arr2]) {
  for (const [name, arr] of [['arr1', arr1], ['arr2', arr2]]) {
    if (!Array.isArray(arr) || arr.length < 1 || arr.length > 1000) return `${name} needs 1 to 1000 digits.`;
    if (arr.some(d => d !== 0 && d !== 1)) return `${name} may contain only 0 and 1.`;
    if (arr.length > 1 && arr[0] !== 1) return `${name} must not have leading zeros.`;
  }
  return null;
}

