  const result = [];
  let i = arr1.length - 1;
  let j = arr2.length - 1;
  let carry = 0;

  while (i >= 0 || j >= 0 || carry !== 0) {
    let sum = carry;
    if (i >= 0) {
      sum += arr1[i];
      i--;
    }
    if (j >= 0) {
      sum += arr2[j];
      j--;
    }
    const digit = sum & 1;
    result.push(digit);
    carry = (digit - sum) / 2;
  }

  while (result.length > 1 && result[result.length - 1] === 0) {
    result.pop();
  }
  return result.reverse();
}

