function addNegabinary(arr1, arr2) {
  // Convert both to exact big integers, add, and convert the total back to base -2.
  const toValue = (arr) => arr.reduce((acc, d) => acc * -2n + BigInt(d), 0n);
  let n = toValue(arr1) + toValue(arr2);
  if (n === 0n) return [0];
  const digits = [];
  while (n !== 0n) {
    const r = n % 2n === 0n ? 0n : 1n;
    digits.unshift(Number(r));
    n = (n - r) / -2n;
  }
  return digits;
}

