function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  // Length 0 stands for the number zero, written [0].
  const make = (length) => length === 0 ? [0] : [1, ...Array.from({ length: length - 1 }, () => int(0, 1))];
  const pick = () => size === 'large' ? int(900, 1000) : int(0, 6);
  const arr1 = make(pick());
  if (rand() < 0.25) {
    // Sometimes add the exact opposite of arr1 (or one more than it), so the digits cancel out.
    let value = 0n;
    for (const d of arr1) value = value * -2n + BigInt(d);
    let n = -value + (rand() < 0.5 ? 0n : 1n);
    const digits = [];
    while (n !== 0n) { const r = n % 2n === 0n ? 0n : 1n; digits.unshift(Number(r)); n = (n - r) / -2n; }
    const arr2 = digits.length ? digits : [0];
    if (arr2.length <= 1000) return rand() < 0.5 ? [arr1, arr2] : [arr2, arr1];
  }
  return [arr1, make(pick())];
